const phone = $('Record AI Sent').first().json.phone || 'unknown';
const aiText = $('Record AI Sent').first().json.text || '';
console.log('WhatsApp reply sent to:', phone, '| Reply:', aiText.substring(0, 50));
return [{json: {success: true, phone, aiReplyPreview: aiText.substring(0, 100), timestamp: new Date().toISOString()}}];

const body = $input.first().json.body;
return [{
  json: {
    phone: body.phone || '',
    type: 'STATUS',
    event: body.event || '',
    messageBy: body.messageBy || '',
    agentId: body.agentId || '',
    automationBy: body.automationBy || '',
    msgId: body.id || '',
    savedAt: new Date().toISOString()
  }
}];

// Decide whether an AGENT status event is OUR AI's own message (echo) or a real
// human agent taking over. QuickReply marks BOTH as messageBy=AGENT, so we match
// against ids/counter recorded when WE sent, with a short time-window + pending
// counter as safety nets against pausing ourselves.
const s = $('Prepare Status Data').first().json;
const phone = s.phone;
const event = s.event;
const messageBy = s.messageBy;
const id = s.msgId;

// Only agent SEND events can be a human takeover. Ignore DELIVERED/READ and all
// AUTOMATION (journeys / chatbot) events.
if (messageBy !== 'AGENT' || event !== 'SENT') {
  return [{ json: { phone, isHuman: false, reason: 'not_agent_send' } }];
}

const ECHO_WINDOW_MS = 20000;
const gs = $getWorkflowStaticData('global');
if (!gs.aiSent) gs.aiSent = { ids: {}, pending: 0, lastAt: 0 };
const now = Date.now();

// No recent AI send => no legit echoes pending.
if (now - (gs.aiSent.lastAt || 0) > 120000) gs.aiSent.pending = 0;

let isEcho = false;
if (id && gs.aiSent.ids[id]) {
  isEcho = true;
  delete gs.aiSent.ids[id];
  if (gs.aiSent.pending > 0) gs.aiSent.pending--;
} else if (gs.aiSent.pending > 0) {
  isEcho = true;
  gs.aiSent.pending--;
} else if (now - (gs.aiSent.lastAt || 0) < ECHO_WINDOW_MS) {
  isEcho = true;
}

const isHuman = !isEcho;
if (isHuman) {
  if (!gs.handoff) gs.handoff = {};
  gs.handoff[phone] = { lastHumanAt: now };
}

return [{ json: {
  phone,
  isHuman,
  type: isHuman ? 'HUMAN_AGENT_MESSAGE' : 'STATUS_ECHO',
  savedAt: new Date().toISOString(),
  msgTime: now,
  msgId: id || '',
  agentId: s.agentId || ''
} }];
